"""Offline browser for the complete, repository-only catalogue.

The embedded payload is lossless. Rendering creates one page of inventory rows
at a time and treats every catalogue string as data, including source excerpts.
"""
from __future__ import annotations

import json
from typing import Any


def render_repository_layer(catalog: dict[str, Any]) -> str:
    """Return a self-contained HTML inspector for repository_layer.v1.

    Refuse a mixed opportunity/workflow graph: evidence and precise capability
    review remain distinct from the number of repositories and captured files.
    """
    if not isinstance(catalog, dict) or catalog.get("schema") != "cite_refinery.repository_layer.v1":
        raise ValueError("expected cite_refinery.repository_layer.v1")
    if catalog.get("scope") != "repository_only":
        raise ValueError("repository-only scope required")
    repositories = catalog.get("repositories")
    if not isinstance(repositories, list):
        raise ValueError("repositories must be a complete list")
    ids = []
    for record in repositories:
        if not isinstance(record, dict) or not isinstance(record.get("id"), str) or not record["id"]:
            raise ValueError("each repository needs an identity")
        ids.append(record["id"])
    if len(set(ids)) != len(ids):
        raise ValueError("duplicate repository identity would hide records")
    for field in ("sources", "relationships"):
        if not isinstance(catalog.get(field, []), list):
            raise ValueError(field + " must be a list")
    payload = json.dumps(catalog, ensure_ascii=False, allow_nan=False, separators=(",", ":"))
    for raw, escaped in (("&", "\\u0026"), ("<", "\\u003c"), (">", "\\u003e"),
                         ("\u2028", "\\u2028"), ("\u2029", "\\u2029")):
        payload = payload.replace(raw, escaped)
    return _HTML.replace("__CATALOG_PAYLOAD__", payload)


